gJQ(){return"Band Calendar"},
gfI(){return"Cancel"},
gKc(){return"Confirm"},
gOB(){return"Settings"},
ga0E(){return"ACCOUNT"},
ga0t(){return"Edit personal data"},
gOy(){return"Change Password"},
ga0x(){return"Send feedback"},
ga0v(){return"Feedback and support"},
ga0u(){return"Send quick feedback directly from the app."},
ga0z(){return"Quick feedback"},
ga0y(){return"Write your feedback here"},
ga0B(){return"Send feedback"},
ga0w(){return"Enter feedback before sending."},
